"""Validate tracker CSVs. Usage: python validate.py [data_dir]"""
import csv
import re
import sys
from pathlib import Path

CATEGORIES = {"evals", "deployment-gating", "disclosure", "security",
              "incident-reporting", "governance", "other"}
SPECIFICITY = {"specific-and-checkable", "vague"}
STATUS = {"in-effect", "revised", "withdrawn", "superseded"}
EVIDENCE_TYPES = {"published-eval", "system-card", "incident-disclosure",
                  "framework-revision", "third-party-report"}
ASSESSMENTS = {"consistent", "partial", "inconsistent", "unclear"}
DATE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
URL = re.compile(r"^https?://")


def check_commitments(path):
    errors, ids = [], set()
    with open(path, newline="", encoding="utf-8") as f:
        for n, row in enumerate(csv.DictReader(f), start=2):
            def err(msg):
                errors.append(f"{path.name}:{n}: {msg}")
            if not row["id"] or row["id"] in ids:
                err(f"missing or duplicate id {row['id']!r}")
            ids.add(row["id"])
            if not DATE.match(row["date_made"] or ""):
                err("date_made must be YYYY-MM-DD")
            if len((row["commitment_text"] or "").split()) > 60:
                err("commitment_text over 60 words")
            if row["category"] not in CATEGORIES:
                err(f"bad category {row['category']!r}")
            if row["specificity"] not in SPECIFICITY:
                err(f"bad specificity {row['specificity']!r}")
            if row["status"] not in STATUS:
                err(f"bad status {row['status']!r}")
            for col in ("source_url", "archive_url"):
                if not URL.match(row[col] or ""):
                    err(f"{col} must be an http(s) URL")
    return errors, ids


def check_evidence(path, commitment_ids):
    errors = []
    with open(path, newline="", encoding="utf-8") as f:
        for n, row in enumerate(csv.DictReader(f), start=2):
            def err(msg):
                errors.append(f"{path.name}:{n}: {msg}")
            if row["commitment_id"] not in commitment_ids:
                err(f"unknown commitment_id {row['commitment_id']!r}")
            if not DATE.match(row["date"] or ""):
                err("date must be YYYY-MM-DD")
            if row["evidence_type"] not in EVIDENCE_TYPES:
                err(f"bad evidence_type {row['evidence_type']!r}")
            if row["assessment"] not in ASSESSMENTS:
                err(f"bad assessment {row['assessment']!r}")
            if row["assessment"] != "unclear" and not (row["reviewer_1"] and row["reviewer_2"]):
                err("non-'unclear' assessments need two reviewers")
            for col in ("source_url", "archive_url"):
                if not URL.match(row[col] or ""):
                    err(f"{col} must be an http(s) URL")
    return errors


def main():
    data = Path(sys.argv[1] if len(sys.argv) > 1 else Path(__file__).parent.parent / "data")
    errors, ids = check_commitments(data / "commitments.csv")
    errors += check_evidence(data / "evidence.csv", ids)
    for e in errors:
        print(e)
    print(f"{len(ids)} commitments checked, {len(errors)} problem(s).")
    sys.exit(1 if errors else 0)


if __name__ == "__main__":
    main()
